window.HSDH_DATA=window.HSDH_DATA||{};window.HSDH_DATA["10-3"]={"ten":"Động lực học","sach":"Kết nối tri thức với cuộc sống","moDau":{"B13":["Hai tàu kéo giống nhau dùng dây cáp kéo một tàu chở hàng bị chết máy. Tàu chở hàng sẽ chuyển động theo hướng nào? Làm thế nào để tính được độ lớn của lực kéo tác dụng lên tàu?","56"],"B14":["Hai tàu Voyager đã tắt động cơ nhưng vẫn tiếp tục bay. Lực có phải là nguyên nhân làm cho vật chuyển động và duy trì chuyển động đó hay không?","60"],"B15":["Đẩy một xe chở hàng cho nó chuyển động. Gia tốc của xe tăng hay giảm nếu: giữ nguyên lực đẩy nhưng khối lượng xe tăng lên; giữ nguyên khối lượng nhưng lực đẩy tăng lên?","63"]},"bai":[{"ma":"B13","ten":"Bài 13. Tổng hợp và phân tích lực. Cân bằng lực","trang_sgk":"56–59","kien_thuc":[{"y":"Tổng hợp lực: là phép thay thế các lực tác dụng đồng thời vào cùng một vật bằng một lực có tác dụng giống hệt như các lực ấy. Lực thay thế gọi là hợp lực. Về mặt toán học, hợp lực là tổng vectơ: $\\vec{F} = \\vec{F}_1 + \\vec{F}_2 + \\dots$","dau":""},{"y":"Hai lực cùng phương: cùng chiều thì $F = F_1 + F_2$; ngược chiều thì $F = |F_1 - F_2|$ và hợp lực cùng chiều với lực lớn hơn.","dau":""},{"y":"Hai lực đồng quy: dùng quy tắc hình bình hành. Hợp lực là đường chéo (kẻ từ điểm đồng quy) của hình bình hành có hai cạnh là hai lực thành phần.","dau":""},{"y":"Các lực cân bằng: khi tổng hợp các lực tác dụng lên vật bằng 0 thì các lực đó cân bằng nhau, vật đứng yên hoặc chuyển động thẳng đều.","dau":""},{"y":"Các lực không cân bằng: khi hợp lực khác 0 thì vận tốc của vật thay đổi (về độ lớn, về hướng).","dau":""},{"y":"Phân tích lực: là phép thay thế một lực bằng hai lực thành phần có tác dụng giống hệt như lực ấy (ngược với tổng hợp lực). Thường phân tích thành hai lực vuông góc với nhau, theo hai phương mà lực có tác dụng.","dau":""},{"y":"Vật trên mặt phẳng nghiêng góc $\\alpha$: trọng lực được phân tích thành $P_x = P\\sin\\alpha$ (song song mặt phẳng, kéo vật trượt xuống) và $P_y = P\\cos\\alpha$ (vuông góc mặt phẳng, ép vật vào mặt phẳng).","dau":""}],"cong_thuc":[{"latex":"\\vec{F} = \\vec{F}_1 + \\vec{F}_2 + \\vec{F}_3 + \\dots","dieu_kien":"Cộng vectơ, không phải cộng độ lớn. Các lực cùng tác dụng lên một vật.","vi_du_so":"Hai lực cùng phương, ngược chiều $400\\ \\mathrm{N}$ và $300\\ \\mathrm{N}$: hợp lực $100\\ \\mathrm{N}$, cùng chiều với lực $400\\ \\mathrm{N}$.","dau":""},{"latex":"F^2 = F_1^2 + F_2^2 + 2F_1F_2\\cos\\alpha","dieu_kien":"$\\alpha$ là góc giữa hai lực đồng quy. Khi $\\alpha = 90^\\circ$: $F = \\sqrt{F_1^2 + F_2^2}$.","vi_du_so":"$F_1 = 6\\ \\mathrm{N}$, $F_2 = 8\\ \\mathrm{N}$, $\\alpha = 90^\\circ$ thì $F = \\sqrt{36 + 64} = 10\\ \\mathrm{N}$.","dau":""},{"latex":"F = 2F_1\\cos\\dfrac{\\alpha}{2}","dieu_kien":"Hai lực đồng quy có độ lớn bằng nhau ($F_1 = F_2$); hợp lực nằm trên đường phân giác của góc giữa hai lực.","vi_du_so":"$F_1 = F_2 = 8000\\ \\mathrm{N}$, $\\alpha = 30^\\circ$ thì $F = 2 \\cdot 8000 \\cdot \\cos 15^\\circ \\approx 15\\,455\\ \\mathrm{N}$.","dau":""},{"latex":"F_x = F\\cos\\theta,\\quad F_y = F\\sin\\theta","dieu_kien":"$\\theta$ là góc giữa lực $\\vec{F}$ và trục Ox; hai thành phần vuông góc nhau.","vi_du_so":"$F = 100\\ \\mathrm{N}$, $\\theta = 30^\\circ$ thì $F_x \\approx 86{,}6\\ \\mathrm{N}$, $F_y = 50\\ \\mathrm{N}$.","dau":""},{"latex":"P_x = P\\sin\\alpha,\\quad P_y = P\\cos\\alpha","dieu_kien":"Vật trên mặt phẳng nghiêng góc $\\alpha$; Ox song song mặt phẳng nghiêng, Oy vuông góc mặt phẳng nghiêng.","vi_du_so":"$m = 1\\ \\mathrm{kg}$, $g = 9{,}8\\ \\mathrm{m/s^2}$, $\\alpha = 30^\\circ$ thì $P_x = 4{,}9\\ \\mathrm{N}$, $P_y \\approx 8{,}5\\ \\mathrm{N}$.","dau":""}],"dang_bai":[{"dang":"Tổng hợp hai lực cùng phương","nhan_biet":"Hai lực cùng nằm trên một đường thẳng (cùng chiều hoặc ngược chiều).","cach_lam":"Cùng chiều: cộng độ lớn. Ngược chiều: lấy độ lớn lớn trừ độ lớn nhỏ, hợp lực cùng chiều với lực lớn hơn.","vi_du":"B13-TLN4","dau":""},{"dang":"Tổng hợp hai lực đồng quy hợp nhau một góc","nhan_biet":"Đề cho độ lớn hai lực và góc giữa chúng, hoặc cho hợp lực và hỏi góc.","cach_lam":"Vẽ hình bình hành. Dùng $F^2 = F_1^2 + F_2^2 + 2F_1F_2\\cos\\alpha$; nếu $F_1 = F_2$ dùng $F = 2F_1\\cos\\dfrac{\\alpha}{2}$; nếu vuông góc dùng định lí Pythagore.","vi_du":"B13-TL1","dau":""},{"dang":"Nhận biết lực cân bằng, lực không cân bằng","nhan_biet":"Đề mô tả trạng thái của vật: đứng yên, thẳng đều, nhanh dần, đổi hướng.","cach_lam":"Vật đứng yên hoặc chuyển động thẳng đều thì hợp lực bằng 0. Vận tốc thay đổi thì hợp lực khác 0 và cùng hướng với lực lớn hơn (khi hai lực cùng phương).","vi_du":"B13-DS1","dau":""},{"dang":"Phân tích lực thành hai thành phần vuông góc","nhan_biet":"Lực xiên góc so với phương chuyển động, hoặc vật trên mặt phẳng nghiêng.","cach_lam":"Chọn hai trục vuông góc theo phương lực có tác dụng. Chiếu lực lên hai trục: thành phần kề góc dùng cos, thành phần đối góc dùng sin.","vi_du":"B13-TL2","dau":""}],"loi_hay_mac":[{"y":"Cộng độ lớn $F = F_1 + F_2$ cho mọi trường hợp; hệ thức này chỉ đúng khi hai lực cùng hướng.","dau":""},{"y":"Nhầm góc $\\alpha$ giữa hai lực với góc giữa một lực và hợp lực, hoặc dùng dấu trừ trước $2F_1F_2\\cos\\alpha$ (dấu trừ là của định lí cosin trong tam giác, với góc trong tam giác).","dau":""},{"y":"Cho rằng vật cân bằng thì phải đứng yên; vật chuyển động thẳng đều cũng có hợp lực bằng 0.","dau":""},{"y":"Trên mặt phẳng nghiêng viết ngược $P_x = P\\cos\\alpha$, $P_y = P\\sin\\alpha$. Cách kiểm tra: khi $\\alpha = 0$ (mặt ngang) thì thành phần kéo vật trượt phải bằng 0.","dau":""}],"hinh":[],"the":[{"mat_truoc":"Tổng hợp lực là gì?","mat_sau":"Thay các lực tác dụng đồng thời vào cùng một vật bằng một lực có tác dụng giống hệt như các lực ấy (hợp lực)."},{"mat_truoc":"Hai lực cùng phương, ngược chiều: hợp lực có độ lớn và chiều thế nào?","mat_sau":"$F = |F_1 - F_2|$, cùng chiều với lực lớn hơn."},{"mat_truoc":"Quy tắc tìm hợp lực của hai lực đồng quy.","mat_sau":"Quy tắc hình bình hành: hợp lực là đường chéo kẻ từ điểm đồng quy."},{"mat_truoc":"Hai lực vuông góc $F_1$, $F_2$: độ lớn hợp lực?","mat_sau":"$F = \\sqrt{F_1^2 + F_2^2}$."},{"mat_truoc":"Điều kiện để các lực tác dụng lên một vật cân bằng nhau.","mat_sau":"Hợp lực bằng 0: $\\vec{F}_1 + \\vec{F}_2 + \\dots = \\vec{0}$."},{"mat_truoc":"Trọng lực của vật trên mặt phẳng nghiêng góc $\\alpha$ được phân tích thế nào?","mat_sau":"$P_x = P\\sin\\alpha$ (kéo vật trượt xuống), $P_y = P\\cos\\alpha$ (ép vật vào mặt phẳng)."}],"cau_hoi":[{"id":"B13-TN1","dang":"tn","muc":"","nguon":"Bài 13","de":"Một vật chịu tác dụng của hai lực $\\vec{F}_{1}$, $\\vec{F}_{2}$ đồng quy. Hợp lực $\\vec{F}$ được xác định bằng công thức","hinh":[],"dau":"","sinh":null,"tn":{"phuong_an":["$\\vec{F}$ = $\\vec{F}_{1}$ + $\\vec{F}_{2}$ (cộng vectơ)","F = $F_{1}$ + $F_{2}$ (luôn đúng)","$\\vec{F}$ = $\\vec{F}_{1}$ − $\\vec{F}_{2}$","F = $F_{1}$ · $F_{2}$"],"dap_an":"A","giai_thich":"Hợp lực là tổng vectơ; F = F₁ + F₂ về độ lớn chỉ đúng khi hai lực cùng hướng."}},{"id":"B13-TN2","dang":"tn","muc":"","nguon":"Bài 13","de":"Tổng hợp lực là phép","hinh":[],"dau":"","sinh":null,"tn":{"phuong_an":["thay thế một lực bằng nhiều lực khác có độ lớn nhỏ hơn.","thay thế các lực tác dụng đồng thời vào cùng một vật bằng một lực có tác dụng giống hệt các lực ấy.","cộng độ lớn của tất cả các lực tác dụng lên vật.","phân tích một lực thành hai lực thành phần."],"dap_an":"B","giai_thich":"Đúng định nghĩa SGK tr. 56. Phân tích lực là phép ngược lại."}},{"id":"B13-TN3","dang":"tn","muc":"","nguon":"Bài 13","de":"Điều kiện để một vật ở trạng thái cân bằng dưới tác dụng của nhiều lực là","hinh":[],"dau":"","sinh":null,"tn":{"phuong_an":["tổng hợp các lực tác dụng lên vật phải dương.","tổng hợp các lực tác dụng lên vật phải âm.","tổng hợp các lực tác dụng lên vật bằng 0.","các lực tác dụng lên vật phải từng đôi một cân bằng."],"dap_an":"C","giai_thich":"Công thức (13.2): hợp lực bằng 0. Không nhất thiết từng đôi một cân bằng (ví dụ ba lực)."}},{"id":"B13-TN4","dang":"tn","muc":"","nguon":"Bài 13","de":"Hai lực đồng quy $\\vec{F}_{1}$, $\\vec{F}_{2}$ vuông góc nhau như hình. Hợp lực $\\vec{F}$ có độ lớn","hinh":[],"dau":"","sinh":null,"anh":"B13/q13_133","tn":{"phuong_an":["F = $F_{1}$ + $F_{2}$","F = |$F_{1}$ − $F_{2}$|","F = √($F_{1}$² + $F_{2}$²)","F = $F_{1}$·$F_{2}$"],"dap_an":"C","giai_thich":"Hình bình hành là hình chữ nhật ⇒ định lí Pythagore."}},{"id":"B13-TN5","dang":"tn","muc":"","nguon":"Bài 13","de":"Hình nào dưới đây biểu diễn một vật chịu tác dụng của hai lực không cân bằng?","hinh":[],"dau":"","sinh":null,"anh":"B13/q13_135","tn":{"phuong_an":["Hình 4","Hình 1","Hình 2","Hình 3"],"dap_an":"D","giai_thich":"Hình 3: F₁ = 5 N ≠ F₂ = 8 N ⇒ hợp lực 3 N ≠ 0. Các hình còn lại: hai lực bằng nhau, ngược chiều."}},{"id":"B13-TN6","dang":"tn","muc":"","nguon":"Bài 13","de":"Một gàu nước có trọng lượng 40 N được kéo lên bởi lực căng dây không đổi 48 N. Lực tổng hợp $\\vec{F}$ = $\\vec{P}$ + $\\vec{T}$ tác dụng vào gàu nước có","hinh":[],"dau":"","sinh":null,"anh":"B13/q13_136","tn":{"phuong_an":["phương thẳng đứng, chiều hướng xuống.","phương thẳng đứng, chiều hướng lên.","phương nằm ngang, sang trái.","phương nằm ngang, sang phải."],"dap_an":"B","giai_thich":"F = 48 − 40 = 8 N, cùng hướng với lực căng (hướng lên)."}},{"id":"B13-TN7","dang":"tn","muc":"","nguon":"Bài 13","de":"Siêu tàu Ever Given bị mắc cạn ở kênh đào Suez (23/03/2021). Hai tàu kéo có F₁ = F₂ = $10^{11}$ N, hai lực hợp nhau góc α = 40°. Hợp lực tác dụng lên siêu tàu có độ lớn","hinh":[],"dau":"","sinh":null,"anh":"B13/q13_155","tn":{"phuong_an":["1,14·$10^{11}$ N","1,54·$10^{11}$ N","2,23·$10^{11}$ N","1,88·$10^{11}$ N"],"dap_an":"D","giai_thich":"F = 2F₁cos(α/2) = 2·10¹¹·cos20° ≈ 1,88·10¹¹ N."}},{"id":"B13-TN8","dang":"tn","muc":"","nguon":"Bài 13","de":"Một cậu bé kéo thùng hàng trên mặt đất bằng sợi dây hợp với phương ngang góc 30°. Lực kéo của cậu bé tác dụng lên dây là 12 N. Độ lớn lực kéo thành phần theo phương vuông góc với mặt đất là","hinh":[],"dau":"","sinh":null,"anh":"B13/q13_172","tn":{"phuong_an":["12√3 N","12 N","6√3 N","6 N"],"dap_an":"D","giai_thich":"$F_{y}$ = F·sin30° = 12·0,5 = 6 N (thành phần ngang $F_{x}$ = 12cos30° = 6√3 N)."}},{"id":"B13-DS1","dang":"ds","muc":"","nguon":"Bài 13","de":"Một người kéo tủ lạnh trên sàn bằng lực $\\vec{F}_{K}$; tủ chịu lực cản $\\vec{F}_{c}$ cùng phương, ngược chiều với $\\vec{F}_{K}$. Nhận định nào đúng, nào sai?","hinh":[],"dau":"","sinh":null,"ds":{"dan":"Một người kéo tủ lạnh trên sàn bằng lực $\\vec{F}_{K}$; tủ chịu lực cản $\\vec{F}_{c}$ cùng phương, ngược chiều với $\\vec{F}_{K}$. Nhận định nào đúng, nào sai?","y":[{"nhan":"a","noi_dung":"Khi tủ lạnh chưa chuyển động thì $F_{K}$ và $F_{c}$ là hai lực cân bằng.","dung":true,"giai_thich":""},{"nhan":"b","noi_dung":"Khi tủ lạnh bắt đầu chuyển động nhanh dần thì $F_{K}$ và $F_{c}$ là hai lực không cân bằng.","dung":true,"giai_thich":""},{"nhan":"c","noi_dung":"Khi tủ lạnh chuyển động nhanh dần, hợp lực cùng hướng với $F_{c}$.","dung":false,"giai_thich":"Hợp lực cùng hướng với lực lớn hơn, tức $F_{K}$."},{"nhan":"d","noi_dung":"Khi $F_{K}$ = 100 N và $F_{c}$ = 40 N thì hợp lực có độ lớn 140 N.","dung":false,"giai_thich":"F = 100 − 40 = 60 N (hai lực ngược chiều)."}]}},{"id":"B13-DS2","dang":"ds","muc":"","nguon":"Bài 13","de":"Một vật chỉ chịu tác dụng của hai lực đồng quy $\\vec{F}_{1}$, $\\vec{F}_{2}$; $\\vec{F}$ là hợp lực của chúng. Nhận định nào đúng, nào sai?","hinh":[],"dau":"","sinh":null,"ds":{"dan":"Một vật chỉ chịu tác dụng của hai lực đồng quy $\\vec{F}_{1}$, $\\vec{F}_{2}$; $\\vec{F}$ là hợp lực của chúng. Nhận định nào đúng, nào sai?","y":[{"nhan":"a","noi_dung":"Độ lớn hợp lực lớn nhất khi hai lực cùng hướng.","dung":true,"giai_thich":""},{"nhan":"b","noi_dung":"Độ lớn hợp lực nhỏ nhất khi hai lực ngược hướng.","dung":true,"giai_thich":""},{"nhan":"c","noi_dung":"Độ lớn lực tổng hợp luôn là F = $F_{1}$ + $F_{2}$.","dung":false,"giai_thich":"Chỉ đúng khi hai lực cùng hướng."},{"nhan":"d","noi_dung":"Nếu vật đứng yên thì hai lực là hai lực cân bằng.","dung":true,"giai_thich":""}]}},{"id":"B13-TLN1","dang":"tln","muc":"","nguon":"Bài 13","de":"Hai lực đồng quy $\\vec{F}_{1}$ và $\\vec{F}_{2}$ có cùng độ lớn 30 N. Để lực tổng hợp cũng có độ lớn 30 N thì góc giữa hai lực bằng bao nhiêu độ?","hinh":[],"dau":"","sinh":null,"tln":{"dap_so":120,"don_vi":"độ","dung_sai":0.5,"cach_giai":"F = 2F₁cos(α/2) = 30 ⇒ cos(α/2) = 0,5 ⇒ α/2 = 60° ⇒ α = 120°."}},{"id":"B13-TLN2","dang":"tln","muc":"","nguon":"Bài 13","de":"Phân tích lực $\\vec{F}$ có độ lớn F = 40√2 N thành hai lực $\\vec{F}_{1}$, $\\vec{F}_{2}$ theo hai phương OA và OB vuông góc nhau như hình vẽ (góc α ở hai bên bằng nhau). Độ lớn của $\\vec{F}_{1}$ bằng bao nhiêu newton? (làm tròn đến phần nguyên)","hinh":[],"dau":"","sinh":null,"anh":"B13/q13_173","tln":{"dap_so":40,"don_vi":"N","dung_sai":0.5,"cach_giai":"α = 45° ⇒ F₁ = F·cos45° = 40√2·(√2/2) = 40 N."}},{"id":"B13-TL1","dang":"tl","muc":"","nguon":"Bài 13","de":"Một ô tô bị hỏng động cơ được hai người dùng hai sợi dây kéo bằng hai lực có độ lớn không đổi F₁ = 500 N và F₂ = 600 N. a) Khi hai dây hợp nhau góc 60°, tính độ lớn hợp lực tác dụng lên ô tô. b) Đề xuất phương án để lực tổng hợp lớn nhất có thể; tính độ lớn lực đó.","hinh":[],"dau":"","sinh":null,"anh":"B13/q13_175","tl":{"loi_giai_mau":"a) F² = F₁² + F₂² + 2F₁F₂cos60° = 500² + 600² + 2·500·600·0,5 = 910 000 ⇒ F ≈ 953,94 N. b) Hai dây song song, cùng chiều (α = 0°): $F_{max}$ = F₁ + F₂ = 1100 N."}},{"id":"B13-TL2","dang":"tl","muc":"","nguon":"Bài 13","de":"Vật khối lượng 1 kg nằm yên trên mặt phẳng nghiêng góc 30° so với phương ngang. Hệ trục Oxy: Ox song song mặt phẳng nghiêng, Oy vuông góc mặt phẳng nghiêng. Lấy g = 9,8 m/s². a) Tính độ lớn thành phần trọng lực theo Ox. b) Tính độ lớn thành phần trọng lực theo Oy.","hinh":[],"dau":"","sinh":null,"anh":"B13/q13_176","tl":{"loi_giai_mau":"P = mg = 9,8 N. a) $P_{x}$ = P·sin30° = 9,8·0,5 = 4,9 N. b) $P_{y}$ = P·cos30° = 9,8·0,866 ≈ 8,5 N."}},{"id":"B13-TLN3","dang":"tln","muc":"","nguon":"SGK","de":"(SGK tr. 57) Cho hai lực đồng quy có độ lớn F₁ = 6 N và F₂ = 8 N. Nếu hợp lực có độ lớn F = 10 N thì góc giữa hai lực bằng bao nhiêu độ?","hinh":[],"dau":"","sinh":null,"tln":{"dap_so":90,"don_vi":"độ","dung_sai":0.5,"cach_giai":"$\\cos\\alpha=\\dfrac{F^2-F_1^2-F_2^2}{2F_1F_2}=\\dfrac{100-36-64}{96}=0$ ⇒ α = 90°."}},{"id":"B13-TL3","dang":"tl","muc":"","nguon":"SGK","de":"(SGK tr. 57) Lực kéo của mỗi tàu kéo đều có độ lớn 8 000 N, góc giữa hai dây cáp bằng 30°. a) Biểu diễn các lực kéo và hợp lực. b) Tính độ lớn hợp lực. c) Xác định phương, chiều hợp lực. d) Nếu góc giữa hai dây bằng 90° thì hợp lực thế nào?","hinh":[],"dau":"","sinh":null,"anh":"B13/s13_tau","tl":{"loi_giai_mau":"a) Dựng hình bình hành (hình thoi) có hai cạnh là hai lực kéo; hợp lực là đường chéo. b) $F=2F_1\\cos\\dfrac{\\alpha}{2}=2\\cdot8000\\cdot\\cos15^\\circ\\approx\\mathbf{15\\,455}\\,\\mathrm{N}$. c) Trùng đường phân giác của góc giữa hai dây, hướng về phía trước. d) α = 90°: $F=8000\\sqrt{2}\\approx\\mathbf{11\\,314}\\,\\mathrm{N}$, vẫn theo phân giác."}},{"id":"B13-DS3","dang":"ds","muc":"","nguon":"SGK","de":"(SGK tr. 58, Hình 13.7) Đúng hay sai?","hinh":[],"dau":"","sinh":null,"anh":"B13/s13_7","ds":{"dan":"(SGK tr. 58, Hình 13.7) Đúng hay sai?","y":[{"nhan":"a","noi_dung":"Bút chì nằm yên: hợp lực bằng 0.","dung":true,"giai_thich":""},{"nhan":"b","noi_dung":"Đẩy bút chì chuyển động nhanh dần: hợp lực khác 0.","dung":true,"giai_thich":""},{"nhan":"c","noi_dung":"Quả bóng nằm yên gần mép bàn: hợp lực khác 0.","dung":false,"giai_thich":"Bóng đứng yên ⇒ hợp lực bằng 0."},{"nhan":"d","noi_dung":"Quả bóng vừa rơi khỏi mép bàn: hợp lực khác 0.","dung":true,"giai_thich":""}]}},{"id":"B13-TLN4","dang":"tln","muc":"","nguon":"SGK","de":"(SGK tr. 58, Hình 13.6) Ô tô chịu lực F₁ = 400 N hướng về phía trước và lực F₂ = 300 N hướng về phía sau. Hợp lực tác dụng lên ô tô có độ lớn bao nhiêu newton?","hinh":[],"dau":"","sinh":null,"anh":"B13/s13_6","tln":{"dap_so":100,"don_vi":"N","dung_sai":0.5,"cach_giai":"Hai lực ngược chiều: F = 400 − 300 = 100 N, hướng về phía trước."}},{"id":"B13-TL4","dang":"tl","muc":"","nguon":"SGK","de":"(SGK tr. 58, Hình 13.5) Quyển sách nằm yên trên mặt bàn. a) Có những lực nào tác dụng lên quyển sách? b) Các lực này có cân bằng không? Vì sao?","hinh":[],"dau":"","sinh":null,"anh":"B13/s13_5","tl":{"loi_giai_mau":"a) Trọng lực $\\vec P$ (hướng xuống) và phản lực $\\vec N$ của mặt bàn (hướng lên). b) Cân bằng: sách đứng yên nên hợp lực bằng 0, hai lực cùng phương, ngược chiều, cùng độ lớn."}},{"id":"B13-TL5","dang":"tl","muc":"","nguon":"SGK","de":"(SGK tr. 59, Hình 13.10) Vật được giữ yên trên mặt phẳng nghiêng nhẵn bởi một lò xo. 1. Có những lực nào tác dụng lên vật? 2. Phân tích trọng lực thành hai lực thành phần và nêu tác dụng của chúng.","hinh":[],"dau":"","sinh":null,"anh":"B13/s13_10","tl":{"loi_giai_mau":"1. Trọng lực $\\vec P$, phản lực $\\vec N$ của mặt phẳng và lực đàn hồi $\\vec F_{đh}$ của lò xo; hợp lực bằng 0. 2. Chọn Ox dọc mặt phẳng (xuống dốc), Oy vuông góc mặt phẳng: $P_x=P\\sin\\alpha$ (kéo vật trượt, cân bằng với lực đàn hồi); $P_y=P\\cos\\alpha$ (ép vật vào mặt phẳng, cân bằng với $N$)."}}]},{"ma":"B14","ten":"Bài 14. Định luật 1 Newton","trang_sgk":"60–62","kien_thuc":[{"y":"Lực và chuyển động: lực không phải là nguyên nhân duy trì chuyển động. Lực làm thay đổi trạng thái chuyển động (thay đổi vận tốc) của vật.","dau":""},{"y":"Thí nghiệm máng nghiêng của Galilei: nếu không có ma sát và máng thứ hai nằm ngang thì viên bi sẽ lăn mãi với vận tốc không đổi.","dau":""},{"y":"Định luật 1 Newton: nếu một vật không chịu tác dụng của lực nào hoặc chịu tác dụng của các lực có hợp lực bằng không, thì vật đang đứng yên sẽ tiếp tục đứng yên, đang chuyển động sẽ tiếp tục chuyển động thẳng đều.","dau":""},{"y":"Quán tính: là tính chất bảo toàn trạng thái đứng yên hay chuyển động của vật. Do có quán tính mà mọi vật đều có xu hướng bảo toàn vận tốc cả về hướng và độ lớn.","dau":""},{"y":"Định luật 1 Newton còn được gọi là định luật quán tính. Khối lượng của vật càng lớn thì quán tính càng lớn, càng khó thay đổi vận tốc.","dau":""},{"y":"Vận dụng quán tính: tra đầu búa vào cán, giật nhanh tờ giấy dưới cốc nước, hành khách bị xô khi xe đổi vận tốc; thắt dây an toàn và giữ khoảng cách an toàn khi tham gia giao thông.","dau":""}],"cong_thuc":[{"latex":"\\vec{F}_{hl} = \\vec{0}\\ \\Rightarrow\\ \\vec{a} = \\vec{0}\\quad(\\vec{v}\\ \\text{không đổi})","dieu_kien":"Vật không chịu lực nào, hoặc các lực tác dụng lên vật có hợp lực bằng 0.","vi_du_so":"Vật đang chuyển động với vận tốc $3\\ \\mathrm{m/s}$, nếu các lực tác dụng lên nó bỗng mất đi thì vật tiếp tục chuyển động thẳng đều với vận tốc $3\\ \\mathrm{m/s}$.","dau":""}],"dang_bai":[{"dang":"Nhận biết nội dung định luật 1 Newton, chuyển động theo quán tính","nhan_biet":"Câu hỏi chọn phát biểu đúng, hoặc hỏi vật nào chuyển động theo quán tính.","cach_lam":"Đối chiếu với định luật: hợp lực bằng 0 thì vật giữ nguyên vận tốc (đứng yên hoặc thẳng đều). Chuyển động theo quán tính là chuyển động tiếp diễn khi không còn lực (hoặc hợp lực bằng 0).","vi_du":"B14-TN3","dau":""},{"dang":"Từ trạng thái chuyển động suy ra hợp lực","nhan_biet":"Đề mô tả vật đứng yên, thẳng đều, hoặc cho đồ thị vận tốc – thời gian.","cach_lam":"Vận tốc không đổi (đứng yên, thẳng đều; đoạn nằm ngang trên đồ thị v–t) thì hợp lực bằng 0. Vận tốc thay đổi thì hợp lực khác 0.","vi_du":"B14-TN5","dau":""},{"dang":"Giải thích hiện tượng bằng quán tính","nhan_biet":"Tình huống xe tăng tốc, phanh gấp, rẽ; tra búa; giật giấy; dây an toàn.","cach_lam":"Nêu ba ý: (1) ban đầu vật và vật mang nó cùng trạng thái chuyển động; (2) một vật bị lực làm đổi vận tốc; (3) vật còn lại do quán tính giữ nguyên vận tốc cũ nên bị xô, ngả, văng theo hướng ngược lại so với vật mang.","vi_du":"B14-TL3","dau":""}],"loi_hay_mac":[{"y":"Cho rằng phải có lực tác dụng thì vật mới chuyển động, ngừng tác dụng lực thì vật dừng lại (quan điểm của Aristotle). Thực tế vật dừng lại là do lực ma sát, lực cản.","dau":""},{"y":"Coi quán tính là một lực (\"lực quán tính đẩy người về phía trước\"). Quán tính là tính chất của vật, không phải lực.","dau":""},{"y":"Cho rằng vật đứng yên thì không chịu lực nào; thật ra vật có thể chịu nhiều lực nhưng hợp lực bằng 0.","dau":""},{"y":"Cho rằng vật chuyển động càng nhanh thì quán tính càng lớn; mức quán tính phụ thuộc vào khối lượng của vật.","dau":""}],"hinh":[],"the":[{"mat_truoc":"Phát biểu định luật 1 Newton.","mat_sau":"Nếu vật không chịu lực nào hoặc chịu các lực có hợp lực bằng 0 thì vật đang đứng yên sẽ tiếp tục đứng yên, đang chuyển động sẽ tiếp tục chuyển động thẳng đều."},{"mat_truoc":"Lực có phải là nguyên nhân duy trì chuyển động không?","mat_sau":"Không. Lực là nguyên nhân làm thay đổi vận tốc (trạng thái chuyển động) của vật."},{"mat_truoc":"Quán tính là gì?","mat_sau":"Tính chất bảo toàn trạng thái đứng yên hay chuyển động của vật."},{"mat_truoc":"Xe đang chạy thì phanh gấp, hành khách ngả về phía nào? Vì sao?","mat_sau":"Ngả về phía trước: do quán tính, người có xu hướng giữ nguyên vận tốc cũ trong khi xe giảm tốc."},{"mat_truoc":"Đại lượng nào cho biết mức quán tính của vật?","mat_sau":"Khối lượng: khối lượng càng lớn, quán tính càng lớn."},{"mat_truoc":"Vì sao tàu Voyager tắt động cơ vẫn bay mãi?","mat_sau":"Trong không gian, lực cản và lực hấp dẫn rất nhỏ, hợp lực gần bằng 0 nên tàu chuyển động thẳng đều theo quán tính."}],"cau_hoi":[{"id":"B14-TN1","dang":"tn","muc":"","nguon":"Bài 14","de":"Phát biểu nào sau đây đúng về nội dung của Định luật 1 Newton?","hinh":[],"dau":"","sinh":null,"tn":{"phuong_an":["Lực là nguyên nhân duy trì chuyển động của vật; khi không còn lực tác dụng, vật dừng lại ngay.","Nếu vật không chịu lực nào hoặc chịu các lực có hợp lực bằng 0, thì vật đang đứng yên sẽ tiếp tục đứng yên, đang chuyển động sẽ tiếp tục chuyển động thẳng đều.","Khi hợp lực bằng 0, vật khối lượng lớn chuyển động chậm dần, vật khối lượng nhỏ chuyển động nhanh dần.","Mọi vật đang chuyển động thẳng đều có xu hướng dừng lại do quán tính."],"dap_an":"B","giai_thich":"Đây là phát biểu của Newton (1687). Lực không duy trì chuyển động; lực làm thay đổi trạng thái chuyển động."}},{"id":"B14-TN2","dang":"tn","muc":"","nguon":"Bài 14","de":"Quán tính của một vật là","hinh":[],"dau":"","sinh":null,"tn":{"phuong_an":["trạng thái đứng yên của vật khi có lực tác dụng.","tính chất bảo toàn trạng thái đứng yên hay chuyển động của vật.","khả năng giữ nguyên tốc độ của vật khi có lực tác dụng.","tính chất thay đổi vận tốc đột ngột của vật khi có lực tác dụng."],"dap_an":"B","giai_thich":"Định nghĩa SGK tr. 61."}},{"id":"B14-TN3","dang":"tn","muc":"","nguon":"Bài 14","de":"Vật nào sau đây chuyển động theo quán tính?","hinh":[],"dau":"","sinh":null,"tn":{"phuong_an":["Vật chuyển động tròn đều.","Vật chuyển động trên quỹ đạo thẳng.","Vật chuyển động thẳng đều.","Vật chuyển động rơi tự do."],"dap_an":"C","giai_thich":"Chuyển động theo quán tính = chuyển động thẳng đều khi hợp lực bằng 0."}},{"id":"B14-TN4","dang":"tn","muc":"","nguon":"Bài 14","de":"Xe đồ chơi chuyển động thẳng đều với v = 2 m/s trên sàn nằm ngang nhẵn (bỏ qua ma sát, lực cản). Nếu hợp lực tác dụng lên xe đột ngột biến mất thì xe sẽ","hinh":[],"dau":"","sinh":null,"tn":{"phuong_an":["dừng lại ngay do không còn lực duy trì chuyển động.","chuyển động chậm dần rồi dừng lại.","tiếp tục chuyển động thẳng đều với vận tốc 2 m/s.","chuyển động nhanh dần theo hướng cũ."],"dap_an":"C","giai_thich":"Hợp lực bằng 0 ⇒ vận tốc giữ nguyên (Định luật 1)."}},{"id":"B14-TN5","dang":"tn","muc":"","nguon":"Bài 14","de":"Vật chuyển động có đồ thị vận tốc – thời gian như hình. Trong khoảng thời gian nào hợp lực tác dụng lên vật bằng 0?","hinh":[],"dau":"","sinh":null,"anh":"B14/q14_178","tn":{"phuong_an":["Từ 0 đến 2 s.","Từ 2 s đến 4 s.","Từ 4 s đến 6 s.","Từ 2 s đến 6 s."],"dap_an":"A","giai_thich":"Từ 0 đến 2 s, v không đổi (a = 0) ⇒ hợp lực bằng 0."}},{"id":"B14-TN6","dang":"tn","muc":"","nguon":"Bài 14","de":"Hình bên mô tả trạng thái chuyển động của một xe khách. Chọn phương án phù hợp.","hinh":[],"dau":"","sinh":null,"anh":"B14/q14_181","tn":{"phuong_an":["Hình 1: xe hãm phanh đột ngột; hình 2: xe tăng tốc đột ngột.","Hình 1: xe đứng yên; hình 2: xe hãm phanh đột ngột.","Hình 1: xe tăng tốc đột ngột; hình 2: xe chuyển động thẳng đều.","Hình 1: xe tăng tốc đột ngột; hình 2: xe hãm phanh đột ngột."],"dap_an":"D","giai_thich":"Tăng tốc: người ngả về phía sau (Hình 1). Phanh gấp: người chúi về phía trước (Hình 2)."}},{"id":"B14-TN7","dang":"tn","muc":"","nguon":"Bài 14","de":"Kéo thật nhanh tờ giấy dưới cốc nước đầy: giấy rời khỏi mà cốc không đổ. Nguyên nhân là do","hinh":[],"dau":"","sinh":null,"anh":"B14/q14_179","tn":{"phuong_an":["cốc không chịu lực theo phương ngang.","quán tính, cốc có xu hướng giữ nguyên trạng thái đứng yên.","trọng lực lên cốc lớn hơn lực kéo tờ giấy.","tờ giấy khối lượng nhỏ, không đủ làm cốc di chuyển."],"dap_an":"B","giai_thich":"Lực ma sát tác dụng quá ngắn, không đủ đổi trạng thái của cốc."}},{"id":"B14-TN8","dang":"tn","muc":"","nguon":"Bài 14","de":"Chọn phát biểu đúng.","hinh":[],"dau":"","sinh":null,"tn":{"phuong_an":["Nếu không có lực tác dụng vào vật thì vật không thể chuyển động.","Nếu các lực tác dụng vào vật đột nhiên biến mất thì vật đang chuyển động sẽ dừng lại.","Vật chỉ chuyển động khi có lực tác dụng vào nó.","Khi vật bị biến dạng hoặc thay đổi vận tốc thì phải có lực tác dụng lên vật."],"dap_an":"D","giai_thich":"Lực là nguyên nhân làm thay đổi vận tốc hoặc làm biến dạng vật."}},{"id":"B14-DS1","dang":"ds","muc":"","nguon":"Bài 14","de":"Nhận định tính đúng/sai của các phát biểu sau:","hinh":[],"dau":"","sinh":null,"ds":{"dan":"Nhận định tính đúng/sai của các phát biểu sau:","y":[{"nhan":"a","noi_dung":"Định luật 1 Newton còn được gọi là định luật quán tính.","dung":true,"giai_thich":""},{"nhan":"b","noi_dung":"Mọi vật đều có xu hướng bảo toàn vận tốc cả về hướng và độ lớn.","dung":true,"giai_thich":""},{"nhan":"c","noi_dung":"Chuyển động biến đổi đều được gọi là chuyển động theo quán tính.","dung":false,"giai_thich":"Chuyển động theo quán tính là chuyển động thẳng đều khi hợp lực bằng 0."},{"nhan":"d","noi_dung":"Nếu hợp lực tác dụng lên vật bằng 0 thì vật đang đứng yên tiếp tục đứng yên, đang chuyển động tiếp tục chuyển động thẳng đều.","dung":true,"giai_thich":""}]}},{"id":"B14-DS2","dang":"ds","muc":"","nguon":"Bài 14","de":"Máy bay cất/hạ cánh phải đổi tốc độ rất lớn trong thời gian ngắn nên cần đường băng dài. Đúng/sai?","hinh":[],"dau":"","sinh":null,"anh":"B14/q14_182","ds":{"dan":"Máy bay cất/hạ cánh phải đổi tốc độ rất lớn trong thời gian ngắn nên cần đường băng dài. Đúng/sai?","y":[{"nhan":"a","noi_dung":"Máy bay có quán tính lớn nên phải tăng tốc dần trên đường băng.","dung":true,"giai_thich":""},{"nhan":"b","noi_dung":"Khi tăng tốc trên đường băng, hợp lực tác dụng lên máy bay bằng không.","dung":false,"giai_thich":"Tăng tốc ⇒ hợp lực khác 0."},{"nhan":"c","noi_dung":"Khi tiếp đất, máy bay cần dùng phanh để giảm tốc dần.","dung":true,"giai_thich":""},{"nhan":"d","noi_dung":"Khi hạ cánh, động cơ ngừng nên không còn lực tác dụng, máy bay chậm dần rồi dừng.","dung":false,"giai_thich":"Vẫn còn lực cản (ma sát, không khí)."}]}},{"id":"B14-DS3","dang":"ds","muc":"","nguon":"Bài 14","de":"Ô tô chạy thẳng đều trên đường ngang thì đột ngột phanh gấp. Đúng/sai?","hinh":[],"dau":"","sinh":null,"anh":"B14/q14_183","ds":{"dan":"Ô tô chạy thẳng đều trên đường ngang thì đột ngột phanh gấp. Đúng/sai?","y":[{"nhan":"a","noi_dung":"Do quán tính, thân trên hành khách dừng lại ngay cùng ô tô.","dung":false,"giai_thich":"Thân trên tiếp tục chuyển động về phía trước."},{"nhan":"b","noi_dung":"Phần thân dưới tiếp xúc ghế dừng lại nhanh hơn thân trên.","dung":true,"giai_thich":""},{"nhan":"c","noi_dung":"Dây đai an toàn giữ người trên ghế, hạn chế va đập.","dung":true,"giai_thich":""},{"nhan":"d","noi_dung":"Trẻ em khối lượng nhỏ, quán tính nhỏ nên có thể không cần dây đai.","dung":false,"giai_thich":"Mọi người đều có quán tính; trẻ em vẫn phải được bảo vệ."}]}},{"id":"B14-TL1","dang":"tl","muc":"","nguon":"SGK","de":"(SGK tr. 60) Quyển sách nằm yên trên mặt bàn: phải đẩy thì nó mới dịch chuyển, ngừng đẩy thì nó dừng lại. Vì sao Aristotle kết luận \"cần có lực để duy trì chuyển động\"? Galilei giải thích khác thế nào?","hinh":[],"dau":"","sinh":null,"tl":{"loi_giai_mau":"Aristotle chưa biết đến ma sát: thấy ngừng đẩy thì vật dừng nên cho rằng lực duy trì chuyển động. Galilei chỉ ra vật dừng là do ma sát; nếu không có ma sát, vật chuyển động mãi với vận tốc không đổi ⇒ lực không duy trì chuyển động, lực chỉ làm đổi chuyển động."}},{"id":"B14-TL2","dang":"tl","muc":"","nguon":"SGK","de":"(SGK tr. 61, Hình 14.2) 1. Giải thích tại sao quả cầu đứng yên. 2. Tại sao người trượt ván có thể giữ nguyên vận tốc?","hinh":[],"dau":"","sinh":null,"anh":"B14/s14_2","tl":{"loi_giai_mau":"1. Trọng lực và lực căng dây cân bằng ⇒ hợp lực bằng 0 ⇒ quả cầu đứng yên. 2. Hợp lực lên người (trọng lực, phản lực, ma sát rất nhỏ) xấp xỉ 0 ⇒ theo định luật 1 Newton, người chuyển động thẳng đều."}},{"id":"B14-TL3","dang":"tl","muc":"","nguon":"SGK","de":"(SGK tr. 61) Mô tả và giải thích điều gì xảy ra với hành khách ngồi trong ô tô khi: a) xe đột ngột tăng tốc; b) xe phanh gấp; c) xe rẽ nhanh sang trái.","hinh":[],"dau":"","sinh":null,"tl":{"loi_giai_mau":"Do quán tính, thân người muốn giữ vận tốc cũ. a) Tăng tốc: người ngả về phía sau. b) Phanh gấp: người chúi về phía trước. c) Rẽ trái: người nghiêng sang bên phải."}},{"id":"B14-TN9","dang":"tn","muc":"","nguon":"SGK","de":"(SGK tr. 61) Một vật đang chuyển động với vận tốc 3 m/s. Nếu bỗng nhiên các lực tác dụng lên vật mất đi thì","hinh":[],"dau":"","sinh":null,"tn":{"phuong_an":["vật dừng lại ngay.","vật đổi hướng chuyển động.","vật chuyển động chậm dần rồi dừng lại.","vật tiếp tục chuyển động theo hướng cũ với vận tốc 3 m/s."],"dap_an":"D","giai_thich":"Hợp lực bằng 0 ⇒ chuyển động thẳng đều với vận tốc cũ."}},{"id":"B14-TL4","dang":"tl","muc":"","nguon":"SGK","de":"(SGK tr. 61) Một vật đang nằm yên trên mặt bàn nằm ngang. Tại sao ta có thể khẳng định bàn đã tác dụng một lực lên nó?","hinh":[],"dau":"","sinh":null,"tl":{"loi_giai_mau":"Vật đứng yên ⇒ hợp lực bằng 0. Trọng lực hướng xuống nên phải có một lực cùng độ lớn, hướng lên cân bằng với nó: đó là phản lực của mặt bàn."}},{"id":"B14-TN10","dang":"tn","muc":"","nguon":"SGK","de":"(SGK tr. 62, Hình 14.4) Để tra đầu búa vào cán, nên chọn cách nào?","hinh":[],"dau":"","sinh":null,"anh":"B14/s14_4","tn":{"phuong_an":["Đập mạnh cán xuống đất (Hình a).","Đập mạnh đầu búa xuống đất (Hình b)."],"dap_an":"A","giai_thich":"Cán dừng đột ngột, đầu búa nặng theo quán tính tiếp tục đi xuống nên gắn chặt vào cán."}},{"id":"B14-TL5","dang":"tl","muc":"","nguon":"SGK","de":"(SGK tr. 62) Khi ngồi trên ô tô, tàu lượn cao tốc hoặc máy bay, hành khách luôn được nhắc thắt dây an toàn. Giải thích điều này.","hinh":[],"dau":"","sinh":null,"tl":{"loi_giai_mau":"Khi xe phanh gấp, va chạm hoặc đổi hướng đột ngột, người theo quán tính tiếp tục chuyển động với vận tốc cũ và dễ bị văng/đập vào phía trước. Dây an toàn tạo ngoại lực giữ người gắn với ghế."}},{"id":"B14-TL6","dang":"tl","muc":"","nguon":"SGK","de":"(SGK tr. 62, Hình 14.5) Giải thích hiện tượng cốc nước trên tờ giấy khi dùng tay kéo từ từ và khi giật mạnh tờ giấy.","hinh":[],"dau":"","sinh":null,"anh":"B14/s14_5","tl":{"loi_giai_mau":"Kéo từ từ: lực ma sát tác dụng đủ lâu làm cốc chuyển động theo giấy. Giật mạnh: lực ma sát tác dụng quá ngắn, theo quán tính cốc gần như đứng yên tại chỗ."}},{"id":"B14-TL7","dang":"tl","muc":"","nguon":"SGK","de":"(SGK tr. 61, Hình 14.3) 1. Vì sao khi xe trượt xuống dốc và bị cản lại ở cuối dốc thì vật nhỏ bị văng về phía trước? 2. Làm thế nào để vật trên xe không bị văng?","hinh":[],"dau":"","sinh":null,"anh":"B14/s14_3","tl":{"loi_giai_mau":"1. Xe bị lực cản dừng lại; vật nhỏ trên mặt xe trơn không bị lực cản đáng kể nên theo quán tính giữ vận tốc cũ. 2. Tăng ma sát/cố định vật vào xe, hoặc giảm vận tốc của xe."}},{"id":"B14-TL8","dang":"tl","muc":"","nguon":"SGK","de":"(SGK tr. 62, Em có thể) Chuẩn bị bài thuyết trình khoảng 15 phút: \"Rất nhiều vụ tai nạn giao thông có nguyên nhân từ quán tính.\" Nêu ví dụ và cách phòng tránh.","hinh":[],"dau":"","sinh":null,"tl":{"loi_giai_mau":"Gợi ý: xe phanh gấp khi không giữ khoảng cách; vào cua quá nhanh bị văng khỏi đường; người không thắt dây an toàn lao về phía trước. Cách phòng tránh: giữ khoảng cách an toàn, giảm tốc trước khi vào cua, thắt dây an toàn/đội mũ bảo hiểm, không phanh gấp trên đường trơn."}}]},{"ma":"B15","ten":"Bài 15. Định luật 2 Newton","trang_sgk":"63–66","kien_thuc":[{"y":"Định luật 2 Newton: gia tốc của một vật cùng hướng với lực tác dụng lên vật. Độ lớn của gia tốc tỉ lệ thuận với độ lớn của lực và tỉ lệ nghịch với khối lượng của vật: $\\vec{a} = \\dfrac{\\vec{F}}{m}$.","dau":""},{"y":"Khi vật chịu nhiều lực tác dụng thì $\\vec{F}$ là hợp lực của các lực đó: $\\vec{F} = \\vec{F}_1 + \\vec{F}_2 + \\vec{F}_3 + \\dots$","dau":""},{"y":"Đơn vị lực: $1\\ \\mathrm{N} = 1\\ \\mathrm{kg \\cdot m/s^2}$, là độ lớn của lực gây ra gia tốc $1\\ \\mathrm{m/s^2}$ cho vật có khối lượng $1\\ \\mathrm{kg}$.","dau":""},{"y":"Khối lượng và quán tính: khối lượng là đại lượng đặc trưng cho mức quán tính của vật. Cùng một lực, vật có khối lượng càng lớn thì gia tốc càng nhỏ, càng khó thay đổi vận tốc.","dau":""},{"y":"Thí nghiệm minh hoạ (xe trượt trên đệm khí, hai cổng quang): đo thời gian $t$ đi quãng đường $s$ từ trạng thái nghỉ, tính $a = \\dfrac{2s}{t^2}$. Kết quả: khi khối lượng không đổi thì $a$ tỉ lệ thuận với $F$; khi lực không đổi thì $a$ tỉ lệ thuận với $\\dfrac{1}{m}$. Đồ thị là đường thẳng đi qua gốc tọa độ.","dau":""},{"y":"Vật được kéo trên mặt phẳng ngang có ma sát: $F - F_{ms} = ma$ với $F_{ms} = \\mu mg$.","dau":""}],"cong_thuc":[{"latex":"\\vec{a} = \\dfrac{\\vec{F}}{m}\\ \\Leftrightarrow\\ \\vec{F} = m\\vec{a}","dieu_kien":"$\\vec{F}$ là hợp lực tác dụng lên vật; $m$ tính bằng kg, $F$ bằng N, $a$ bằng $\\mathrm{m/s^2}$. Gia tốc cùng hướng với hợp lực.","vi_du_so":"Quả bóng $0{,}50\\ \\mathrm{kg}$ chịu lực đá $250\\ \\mathrm{N}$: $a = \\dfrac{250}{0{,}5} = 500\\ \\mathrm{m/s^2}$.","dau":""},{"latex":"1\\ \\mathrm{N} = 1\\ \\mathrm{kg \\cdot m/s^2}","dieu_kien":"Định nghĩa đơn vị newton trong hệ SI.","vi_du_so":"Lực $20\\ \\mathrm{N}$ gây gia tốc $0{,}4\\ \\mathrm{m/s^2}$ cho vật có khối lượng $m = \\dfrac{20}{0{,}4} = 50\\ \\mathrm{kg}$.","dau":""},{"latex":"a = \\dfrac{2s}{t^2}","dieu_kien":"Vật chuyển động thẳng nhanh dần đều từ trạng thái nghỉ ($v_0 = 0$), đi quãng đường $s$ trong thời gian $t$.","vi_du_so":"$s = 0{,}5\\ \\mathrm{m}$, $t = 0{,}71\\ \\mathrm{s}$ thì $a \\approx 2{,}0\\ \\mathrm{m/s^2}$.","dau":""},{"latex":"F - F_{ms} = ma,\\quad F_{ms} = \\mu mg","dieu_kien":"Vật trượt trên mặt phẳng nằm ngang, lực kéo nằm ngang.","vi_du_so":"$m = 80\\ \\mathrm{kg}$, $\\mu = 0{,}3$, $g = 9{,}8\\ \\mathrm{m/s^2}$, cần $a = 0{,}2\\ \\mathrm{m/s^2}$: $F = m(a + \\mu g) = 251{,}2\\ \\mathrm{N}$.","dau":""}],"dang_bai":[{"dang":"Tính gia tốc, lực hoặc khối lượng từ $F = ma$","nhan_biet":"Đề cho hai trong ba đại lượng $F$, $m$, $a$.","cach_lam":"Đổi đơn vị về kg, N, $\\mathrm{m/s^2}$ rồi dùng $a = \\dfrac{F}{m}$. Nếu có nhiều lực, tìm hợp lực trước.","vi_du":"B15-TLN5","dau":""},{"dang":"Kết hợp định luật 2 Newton với công thức động học","nhan_biet":"Đề cho lực và thời gian tác dụng, hỏi vận tốc, quãng đường (hoặc ngược lại).","cach_lam":"Bước 1: tìm $a$ từ $a = \\dfrac{F}{m}$ (hoặc từ $v = v_0 + at$, $s = v_0t + \\dfrac{1}{2}at^2$). Bước 2: thay vào công thức còn lại.","vi_du":"B15-TN12","dau":""},{"dang":"So sánh gia tốc khi thay đổi lực hoặc khối lượng","nhan_biet":"Đề cho lực tăng, giảm bao nhiêu lần, khối lượng tăng, giảm bao nhiêu lần.","cach_lam":"Dùng tỉ lệ: $a$ tỉ lệ thuận với $F$ và tỉ lệ nghịch với $m$, lập tỉ số $\\dfrac{a_2}{a_1} = \\dfrac{F_2}{F_1} \\cdot \\dfrac{m_1}{m_2}$.","vi_du":"B15-TN6","dau":""},{"dang":"Đọc đồ thị lực – gia tốc để tìm khối lượng","nhan_biet":"Đề cho đồ thị là đường thẳng qua gốc tọa độ liên hệ $F$ và $a$.","cach_lam":"Chọn một điểm rõ tọa độ trên đồ thị, tính $m = \\dfrac{F}{a}$; sau đó dùng $m$ cho các câu hỏi tiếp theo.","vi_du":"B15-TLN1","dau":""}],"loi_hay_mac":[{"y":"Quên đổi khối lượng từ gam sang kilôgam trước khi thay vào $F = ma$.","dau":""},{"y":"Thay một lực thành phần vào công thức thay cho hợp lực (ví dụ quên trừ lực ma sát, lực cản).","dau":""},{"y":"Cho rằng lực luôn cùng hướng với vận tốc; hợp lực cùng hướng với gia tốc, có thể ngược hướng vận tốc (khi vật chuyển động chậm dần).","dau":""},{"y":"Nhầm khối lượng (kg, đặc trưng cho mức quán tính) với trọng lượng (N, độ lớn của trọng lực).","dau":""}],"hinh":[],"the":[{"mat_truoc":"Phát biểu định luật 2 Newton.","mat_sau":"Gia tốc của vật cùng hướng với lực tác dụng; độ lớn gia tốc tỉ lệ thuận với độ lớn của lực và tỉ lệ nghịch với khối lượng: $\\vec{a} = \\dfrac{\\vec{F}}{m}$."},{"mat_truoc":"$1\\ \\mathrm{N}$ bằng bao nhiêu theo đơn vị cơ bản?","mat_sau":"$1\\ \\mathrm{N} = 1\\ \\mathrm{kg \\cdot m/s^2}$."},{"mat_truoc":"Khối lượng đặc trưng cho điều gì của vật?","mat_sau":"Mức quán tính của vật."},{"mat_truoc":"Lực tăng 2 lần, khối lượng không đổi thì gia tốc thay đổi thế nào?","mat_sau":"Tăng 2 lần ($a$ tỉ lệ thuận với $F$)."},{"mat_truoc":"Khối lượng tăng 2 lần, lực không đổi thì gia tốc thay đổi thế nào?","mat_sau":"Giảm 2 lần ($a$ tỉ lệ nghịch với $m$)."},{"mat_truoc":"Vật chịu nhiều lực thì $\\vec{F}$ trong $\\vec{F} = m\\vec{a}$ là lực nào?","mat_sau":"Hợp lực của tất cả các lực tác dụng lên vật."}],"cau_hoi":[{"id":"B15-TN1","dang":"tn","muc":"","nguon":"Bài 15","de":"Theo định luật 2 Newton, khi vật chịu tác dụng của hợp lực khác không, gia tốc của vật","hinh":[],"dau":"","sinh":null,"tn":{"phuong_an":["tỉ lệ thuận với khối lượng và tỉ lệ nghịch với độ lớn hợp lực.","luôn ngược hướng với hợp lực.","cùng hướng với lực tác dụng, độ lớn tỉ lệ thuận với độ lớn của lực và tỉ lệ nghịch với khối lượng.","luôn vuông góc với hướng của hợp lực."],"dap_an":"C","giai_thich":"$\\vec{a}$ = $\\vec{F}$/m: cùng hướng với hợp lực; a ∝ F; a ∝ 1/m."}},{"id":"B15-TN2","dang":"tn","muc":"","nguon":"Bài 15","de":"Các hình vẽ mô tả hợp lực $\\vec{F}$ tác dụng vào vật và gia tốc $\\vec{a}$ vật thu được (đánh số Hình 1–4 theo thứ tự: trái → phải, trên → dưới). Chọn hình vẽ đúng.","hinh":[],"dau":"","sinh":null,"anh":"B15/q15_184","tn":{"phuong_an":["Hình 1","Hình 2","Hình 3","Hình 4"],"dap_an":"D","giai_thich":"Gia tốc phải cùng hướng với hợp lực: Hình 4 ($\\vec{a}$ cùng chiều $\\vec{F}$)."}},{"id":"B15-TN3","dang":"tn","muc":"","nguon":"Bài 15","de":"Tác dụng lực $\\vec{F}$ vào vật khối lượng m gây ra cho vật gia tốc $\\vec{a}$. Biểu thức định luật 2 Newton là","hinh":[],"dau":"","sinh":null,"tn":{"phuong_an":["$\\vec{a}$ = $\\vec{F}$/m","$\\vec{F}$ = m⃗·$\\vec{a}$ (m là vectơ)","$\\vec{a}$ = m/$\\vec{F}$","F = m·$\\vec{a}$ (vế trái vô hướng)"],"dap_an":"A","giai_thich":"Dạng đúng: $\\vec{a}$ = $\\vec{F}$/m ⇔ $\\vec{F}$ = m·$\\vec{a}$ (hai vế đều là vectơ)."}},{"id":"B15-TN4","dang":"tn","muc":"","nguon":"Bài 15","de":"Trong hệ SI, đơn vị của lực là","hinh":[],"dau":"","sinh":null,"tn":{"phuong_an":["newton (N).","kilôgam (kg).","mét trên giây (m/s).","newton nhân mét (N·m)."],"dap_an":"A","giai_thich":"Lực: newton (N). kg là khối lượng; m/s là vận tốc; N·m là moment lực."}},{"id":"B15-TN5","dang":"tn","muc":"","nguon":"Bài 15","de":"Trong hệ SI, đơn vị của lực là newton (N). 1 N có giá trị bằng","hinh":[],"dau":"","sinh":null,"tn":{"phuong_an":["1 kg·1 m","1 kg·1 m/s²","1 kg/1 m","1 kg/(1 m/s²)"],"dap_an":"B","giai_thich":"F = m·a ⇒ 1 N = 1 kg · 1 m/s²."}},{"id":"B15-TN6","dang":"tn","muc":"","nguon":"Bài 15","de":"Tác dụng hợp lực lên vật khối lượng m làm vật thu gia tốc a. Nếu độ lớn hợp lực tăng 2 lần (m không đổi) thì độ lớn gia tốc của vật","hinh":[],"dau":"","sinh":null,"tn":{"phuong_an":["không đổi.","giảm 2 lần.","tăng 2 lần.","tăng 0,5 lần."],"dap_an":"C","giai_thich":"a = F/m ⇒ a tỉ lệ thuận với F."}},{"id":"B15-TN7","dang":"tn","muc":"","nguon":"Bài 15","de":"Khối lượng là đại lượng đặc trưng cho","hinh":[],"dau":"","sinh":null,"tn":{"phuong_an":["trọng lượng của vật.","tác dụng làm quay của lực quanh một trục.","thể tích của vật.","mức quán tính của vật."],"dap_an":"D","giai_thich":"Cùng một lực, m càng lớn thì gia tốc càng nhỏ ⇒ quán tính càng lớn."}},{"id":"B15-TN8","dang":"tn","muc":"","nguon":"Bài 15","de":"Trong các phương tiện giao thông sau, phương tiện có mức quán tính nhỏ nhất là","hinh":[],"dau":"","sinh":null,"anh":"B15/q15_188","tn":{"phuong_an":["xe đạp.","xe ô tô.","xe tải.","tàu hỏa."],"dap_an":"A","giai_thich":"Khối lượng nhỏ nhất ⇒ quán tính nhỏ nhất."}},{"id":"B15-TN9","dang":"tn","muc":"","nguon":"Bài 15","de":"Bạn A đẩy thùng bằng lực $\\vec{F}_{1}$ làm thùng có gia tốc $\\vec{a}_{1}$ (Hình a); bạn B kéo bằng lực $\\vec{F}_{2}$ làm thùng có gia tốc $\\vec{a}_{2}$ (Hình b). Chọn phát biểu sai:","hinh":[],"dau":"","sinh":null,"anh":"B15/q15_189","tn":{"phuong_an":["Nếu $\\vec{a}_{1}$ = $\\vec{a}_{2}$ thì $\\vec{F}_{1}$ = $\\vec{F}_{2}$.","Nếu độ lớn $a_{1}$ = $a_{2}$ thì hai lực $\\vec{F}_{1}$ và $\\vec{F}_{2}$ bằng nhau.","Nếu $\\vec{a}_{1}$ ≠ $\\vec{a}_{2}$ thì hai lực không bằng nhau.","Nếu $\\vec{a}_{1}$, $\\vec{a}_{2}$ khác hướng, $a_{1}$ = $a_{2}$ thì hai lực không bằng nhau."],"dap_an":"B","giai_thich":"Hai vectơ bằng nhau phải cùng hướng và cùng độ lớn; bằng độ lớn chưa đủ."}},{"id":"B15-TN10","dang":"tn","muc":"","nguon":"Bài 15","de":"Phát biểu nào sau đây là sai?","hinh":[],"dau":"","sinh":null,"tn":{"phuong_an":["Vật chuyển động thẳng nhanh dần đều khi lực tác dụng lên vật có độ lớn tăng dần.","Lực tác dụng vào vật càng lớn thì độ lớn gia tốc càng lớn.","Dưới tác dụng của cùng một lực, vật có khối lượng càng lớn thì gia tốc càng nhỏ.","Vectơ gia tốc của vật luôn cùng hướng với vectơ lực gây ra gia tốc đó."],"dap_an":"A","giai_thich":"Nhanh dần đều khi hợp lực không đổi (a không đổi); lực tăng dần thì a tăng dần."}},{"id":"B15-DS1","dang":"ds","muc":"","nguon":"Bài 15","de":"Nhận xét tính đúng/sai theo Định luật II Newton:","hinh":[],"dau":"","sinh":null,"ds":{"dan":"Nhận xét tính đúng/sai theo Định luật II Newton:","y":[{"nhan":"a","noi_dung":"Gia tốc của một vật luôn cùng hướng với lực tổng hợp tác dụng lên vật.","dung":true,"giai_thich":""},{"nhan":"b","noi_dung":"Với cùng một lực không đổi, vật có khối lượng càng lớn thì gia tốc càng nhỏ.","dung":true,"giai_thich":""},{"nhan":"c","noi_dung":"Khi lực tác dụng lên vật tăng thì gia tốc luôn tăng theo, không phụ thuộc khối lượng.","dung":false,"giai_thich":"a = F/m phụ thuộc cả m."},{"nhan":"d","noi_dung":"Vật chỉ chịu một lực không đổi thì gia tốc tăng dần theo thời gian.","dung":false,"giai_thich":"a = F/m = hằng số."}]}},{"id":"B15-DS2","dang":"ds","muc":"","nguon":"Bài 15","de":"Nhóm HS: (I) giả thuyết \"m không đổi, a tỉ lệ thuận với F\"; (II) bố trí thí nghiệm như hình; (III) tăng số quả nặng, đo a: F tăng thì a tăng; (IV) kết luận đã kiểm chứng (I). Đúng/sai?","hinh":[],"dau":"","sinh":null,"anh":"B15/q15_190","ds":{"dan":"Nhóm HS: (I) giả thuyết \"m không đổi, a tỉ lệ thuận với F\"; (II) bố trí thí nghiệm như hình; (III) tăng số quả nặng, đo a: F tăng thì a tăng; (IV) kết luận đã kiểm chứng (I). Đúng/sai?","y":[{"nhan":"a","noi_dung":"Nhóm thực hiện đúng tiến trình phương pháp thực nghiệm.","dung":true,"giai_thich":""},{"nhan":"b","noi_dung":"Bước (I) là giả thuyết của nhóm.","dung":true,"giai_thich":""},{"nhan":"c","noi_dung":"Khi tăng quả nặng để tăng F, cần tăng khối lượng xe trượt.","dung":false,"giai_thich":"Giữ tổng khối lượng (xe + quả nặng) không đổi."},{"nhan":"d","noi_dung":"Kết quả bước (III) đủ cơ sở chấp nhận kết luận (IV).","dung":false,"giai_thich":"Mới định tính; cần đồ thị a–F thẳng qua gốc."}]}},{"id":"B15-DS3","dang":"ds","muc":"","nguon":"Bài 15","de":"Drone khối lượng 4 kg hạ thẳng đứng từ độ cao 10 m với tốc độ đầu 10 m/s; hợp lực tác dụng lên drone không đổi 12 N, hướng thẳng đứng lên trên. Đúng/sai?","hinh":[],"dau":"","sinh":null,"ds":{"dan":"Drone khối lượng 4 kg hạ thẳng đứng từ độ cao 10 m với tốc độ đầu 10 m/s; hợp lực tác dụng lên drone không đổi 12 N, hướng thẳng đứng lên trên. Đúng/sai?","y":[{"nhan":"a","noi_dung":"Gia tốc của drone hướng thẳng đứng lên trên.","dung":true,"giai_thich":""},{"nhan":"b","noi_dung":"Độ lớn gia tốc của drone là 3 m/s².","dung":true,"giai_thich":"a = F/m = 12/4 = 3 m/s²."},{"nhan":"c","noi_dung":"Drone chuyển động nhanh dần đều vì chịu hợp lực không đổi.","dung":false,"giai_thich":"a ngược hướng v ⇒ chuyển động chậm dần đều."},{"nhan":"d","noi_dung":"Làm tròn đến phần trăm, tốc độ drone khi vừa chạm đất là 6,32 m/s.","dung":true,"giai_thich":"v² = v₀² − 2as = 100 − 60 = 40 ⇒ v ≈ 6,32 m/s."}]}},{"id":"B15-TLN1","dang":"tln","muc":"","nguon":"Bài 15","de":"Khảo sát lực F tác dụng lên vật trượt trên mặt phẳng ngang nhẵn và gia tốc a (đồ thị như hình). Khối lượng của vật là bao nhiêu kg?","hinh":[],"dau":"","sinh":null,"anh":"B15/q15_192","tln":{"dap_so":2,"don_vi":"kg","dung_sai":0.05,"cach_giai":"Điểm (F = 2 N; a = 1 m/s²) ⇒ m = F/a = 2 kg."}},{"id":"B15-TLN2","dang":"tln","muc":"","nguon":"Bài 15","de":"Với vật ở câu trước, khi lực tác dụng có độ lớn 5 N thì gia tốc là bao nhiêu m/s²?","hinh":[],"dau":"","sinh":null,"anh":"B15/q15_192","tln":{"dap_so":2.5,"don_vi":"m/s²","dung_sai":0.05,"cach_giai":"a = F/m = 5/2 = 2,5 m/s²."}},{"id":"B15-TLN3","dang":"tln","muc":"","nguon":"Bài 15","de":"Một lực $\\vec{F}$ không đổi tác dụng lần lượt lên hai vật khối lượng m₁ và m₂ gây ra gia tốc 2 m/s² và 6 m/s². Nếu tác dụng lực đó lên vật khối lượng m = m₁ + m₂ thì gia tốc là bao nhiêu m/s²?","hinh":[],"dau":"","sinh":null,"tln":{"dap_so":1.5,"don_vi":"m/s²","dung_sai":0.05,"cach_giai":"m₁ = F/2; m₂ = F/6 ⇒ m = 2F/3 ⇒ a = F/m = 1,5 m/s²."}},{"id":"B15-TL1","dang":"tl","muc":"","nguon":"Bài 15","de":"Giải thích vì sao biển báo giao thông ở một số đoạn đường quy định tốc độ giới hạn của xe tải (60 km/h) nhỏ hơn xe con (80 km/h).","hinh":[],"dau":"","sinh":null,"anh":"B15/q15_193","tl":{"loi_giai_mau":"Xe tải có khối lượng lớn ⇒ quán tính lớn ⇒ khó thay đổi vận tốc, quãng đường phanh dài hơn; khi va chạm lực tác dụng cũng lớn hơn. Vì vậy xe tải phải có tốc độ giới hạn thấp hơn để bảo đảm an toàn."}},{"id":"B15-TL2","dang":"tl","muc":"","nguon":"Bài 15","de":"Người mua hàng đẩy giỏ xe (hình a) khối lượng 10 kg từ trạng thái nghỉ, sau 2 s xe đạt 4 m/s. a) Tính độ lớn hợp lực tác dụng lên xe. b) Sau khi đặt hàng vào giỏ (hình b), người này cần hợp lực gấp 1,6 lần lúc đầu để xe cũng đạt 4 m/s sau 2 s. Tìm khối lượng hàng hóa.","hinh":[],"dau":"","sinh":null,"anh":"B15/q15_194","tl":{"loi_giai_mau":"a) a = Δv/Δt = 4/2 = 2 m/s² ⇒ F = m·a = 10·2 = 20 N. b) F′ = 1,6·20 = 32 N, a′ = 2 m/s² ⇒ m′ = F′/a′ = 16 kg ⇒ $m_{\\text{hàng}}$ = 16 − 10 = 6 kg."}},{"id":"B15-TL3","dang":"tl","muc":"","nguon":"SGK","de":"(SGK tr. 63) Đẩy một xe chở hàng cho nó chuyển động. Nhận xét gia tốc của xe tăng hay giảm nếu: a) giữ nguyên lực đẩy nhưng khối lượng xe tăng lên; b) giữ nguyên khối lượng nhưng lực đẩy tăng lên.","hinh":[],"dau":"","sinh":null,"anh":"B15/s15_open","tl":{"loi_giai_mau":"a) Gia tốc giảm ($a\\propto 1/m$). b) Gia tốc tăng ($a\\propto F$)."}},{"id":"B15-TL4","dang":"tl","muc":"","nguon":"SGK","de":"(SGK tr. 64) 1. Nêu một số ví dụ cho thấy khối lượng của vật càng lớn thì mức quán tính của vật càng lớn. Điều này có ý nghĩa gì trong thực tiễn?","hinh":[],"dau":"","sinh":null,"tl":{"loi_giai_mau":"Ví dụ: xe tải chở nặng khó dừng hơn xe con; khó đẩy xe chở đầy cát hơn xe rỗng. Ý nghĩa: vật khối lượng lớn khó thay đổi vận tốc nên cần quãng đường phanh dài hơn, cần lực lớn hơn để khởi động/dừng."}},{"id":"B15-TLN4","dang":"tln","muc":"","nguon":"SGK","de":"(SGK tr. 64, Hình 15.1) Cho đồ thị biểu diễn mối liên hệ giữa lực tác dụng lên một vật và gia tốc gây ra. Khối lượng của vật là bao nhiêu kg?","hinh":[],"dau":"","sinh":null,"anh":"B15/s15_g","tln":{"dap_so":0.5,"don_vi":"kg","dung_sai":0.02,"cach_giai":"Điểm (a = 1,0 m/s²; F = 0,5 N) ⇒ m = F/a = 0,5 kg."}},{"id":"B15-TL5","dang":"tl","muc":"","nguon":"SGK","de":"(SGK tr. 65, Bảng 15.1) a) Vẽ đồ thị a theo F (khi M+m = 0,5 kg) và a theo 1/(M+m) (khi F = 1 N). Các đồ thị có phải đường thẳng không? Vì sao? b) Nêu kết luận về sự phụ thuộc của gia tốc vào độ lớn lực và khối lượng.","hinh":[],"dau":"","sinh":null,"anh":"B15/s15_tab","tl":{"loi_giai_mau":"a) Đồ thị là đường thẳng đi qua gốc tọa độ vì a tỉ lệ thuận với F và tỉ lệ thuận với 1/(M+m) (xem tab thao tác ở slide “Số liệu và đồ thị”). b) $a\\propto F$, $a\\propto\\dfrac{1}{m}$ ⇒ $a=\\dfrac{F}{m}$."}},{"id":"B15-TN11","dang":"tn","muc":"","nguon":"SGK","de":"(SGK tr. 66) Trong các cách viết hệ thức của định luật 2 Newton sau đây, cách viết nào đúng?","hinh":[],"dau":"","sinh":null,"tn":{"phuong_an":["$\\vec F=m\\vec a$","$\\vec F=-m\\vec a$","$\\vec F=m a$","$-\\vec F=m\\vec a$"],"dap_an":"A","giai_thich":"Hợp lực bằng khối lượng nhân vectơ gia tốc (cùng hướng)."}},{"id":"B15-TN12","dang":"tn","muc":"","nguon":"SGK","de":"(SGK tr. 66) Quả bóng khối lượng 0,50 kg nằm yên trên mặt đất. Cầu thủ đá bóng bằng lực 250 N, thời gian lực tác dụng 0,02 s. Quả bóng bay đi với tốc độ","hinh":[],"dau":"","sinh":null,"tn":{"phuong_an":["0,01 m/s.","0,10 m/s.","2,50 m/s.","10,00 m/s."],"dap_an":"D","giai_thich":"a = F/m = 500 m/s²; v = a·t = 500·0,02 = 10 m/s."}},{"id":"B15-TLN5","dang":"tln","muc":"","nguon":"SGK","de":"(SGK tr. 66) Dưới tác dụng của hợp lực 20 N, một chiếc xe đồ chơi chuyển động với gia tốc 0,4 m/s². Dưới tác dụng của hợp lực 50 N, xe sẽ chuyển động với gia tốc bao nhiêu m/s²?","hinh":[],"dau":"","sinh":null,"tln":{"dap_so":1,"don_vi":"m/s²","dung_sai":0.02,"cach_giai":"m = 20/0,4 = 50 kg ⇒ a = 50/50 = 1,0 m/s²."}},{"id":"B15-TL6","dang":"tl","muc":"","nguon":"SGK","de":"(SGK tr. 66) Tại sao máy bay có khối lượng càng lớn thì đường băng phải càng dài?","hinh":[],"dau":"","sinh":null,"tl":{"loi_giai_mau":"Với cùng lực đẩy của động cơ, khối lượng càng lớn thì gia tốc $a=F/m$ càng nhỏ, máy bay cần quãng đường dài hơn để đạt tốc độ cất cánh; khi hạ cánh cũng cần quãng đường phanh dài hơn."}},{"id":"B15-TL7","dang":"tl","muc":"","nguon":"SGK","de":"(SGK tr. 66, Em có thể) Đề xuất một thí nghiệm chứng tỏ gia tốc phụ thuộc vào: a) độ lớn của lực tác dụng; b) khối lượng của vật.","hinh":[],"dau":"","sinh":null,"tl":{"loi_giai_mau":"Dùng máng đệm khí, xe trượt, quả nặng và cổng quang điện: a) giữ tổng khối lượng không đổi, tăng dần lực kéo, đo gia tốc; b) giữ lực kéo không đổi, thay đổi khối lượng xe, đo gia tốc."}},{"id":"B15-TL8","dang":"tl","muc":"","nguon":"Mở rộng","de":"Vật khối lượng 2 kg, vận tốc đầu bằng 0, chuyển động thẳng dưới tác dụng của hợp lực có đồ thị F – t như hình [HV: dựng lại theo đáp án đề gốc].t (s)F (N)3−2103040O a) Xác định gia tốc của vật trong 10 s đầu tiên. b) Xác định tốc độ của vật tại thời điểm t = 35 s.","hinh":[],"dau":"","sinh":null,"tl":{"loi_giai_mau":"a) $a=\\dfrac{F}{m}=\\dfrac{3}{2}=\\mathbf{1{,}5}\\,\\mathrm{m/s^2}$. b) $v_{10}=15\\,\\mathrm{m/s}$; 10–30 s: $F=0\\Rightarrow v=15\\,\\mathrm{m/s}$; 30–35 s: $a=-1\\,\\mathrm{m/s^2}\\Rightarrow v=15-1\\cdot5=\\mathbf{10}\\,\\mathrm{m/s}$."}}]}],"sgk":{"H13-tau":{"cap":"Hình mở đầu Bài 13","tr":56,"src":"data:image/jpeg;base64,"},"H13-1":{"cap":"Hình 13.1","tr":56,"src":"data:image/jpeg;base64,"},"H13-2":{"cap":"Hình 13.2","tr":57,"src":"data:image/jpeg;base64,"},"H13-3":{"cap":"Hình 13.3","tr":57,"src":"data:image/jpeg;base64,"},"H13-4":{"cap":"Hình 13.4","tr":58,"src":"data:image/jpeg;base64,"},"H13-5":{"cap":"Hình 13.5","tr":"","src":"data:image/jpeg;base64,"},"H13-6":{"cap":"Hình 13.6","tr":58,"src":"data:image/jpeg;base64,"},"H13-7":{"cap":"Hình 13.7","tr":58,"src":"data:image/jpeg;base64,"},"H14-voy":{"cap":"Tàu Voyager","tr":60,"src":"data:image/jpeg;base64,"},"H14-1":{"cap":"Hình 14.1","tr":60,"src":"data:image/jpeg;base64,"},"H14-2":{"cap":"Hình 14.2","tr":61,"src":"data:image/jpeg;base64,"},"H14-3":{"cap":"Hình 14.3","tr":61,"src":"data:image/jpeg;base64,"},"H14-4":{"cap":"Hình 14.4","tr":62,"src":"data:image/jpeg;base64,"},"H14-5":{"cap":"Hình 14.5","tr":62,"src":"data:image/jpeg;base64,"},"H15-open":{"cap":"Hình mở đầu Bài 15","tr":63,"src":"data:image/jpeg;base64,"},"H15-lab":{"cap":"Hình 15.2","tr":64,"src":"data:image/jpeg;base64,"},"H15-tab":{"cap":"Bảng 15.1","tr":65,"src":"data:image/jpeg;base64,"}},"anh":{"B13/q13_133":"data:image/png;base64,","B13/q13_135":"data:image/jpeg;base64,","B13/q13_136":"data:image/png;base64,","B13/q13_155":"data:image/png;base64,","B13/q13_172":"data:image/jpeg;base64,","B13/q13_173":"data:image/png;base64,","B13/q13_175":"data:image/jpeg;base64,","B13/q13_176":"data:image/png;base64,","B13/s13_tau":"data:image/jpeg;base64,","B13/s13_7":"data:image/jpeg;base64,","B13/s13_6":"data:image/jpeg;base64,","B13/s13_5":"data:image/jpeg;base64,","B13/s13_10":"data:image/jpeg;base64,","B14/q14_178":"data:image/png;base64,","B14/q14_181":"data:image/png;base64,","B14/q14_179":"data:image/jpeg;base64,","B14/q14_182":"data:image/jpeg;base64,","B14/q14_183":"data:image/jpeg;base64,","B14/s14_2":"data:image/jpeg;base64,","B14/s14_4":"data:image/jpeg;base64,","B14/s14_5":"data:image/jpeg;base64,","B14/s14_3":"data:image/jpeg;base64,","B15/q15_184":"data:image/jpeg;base64,","B15/q15_188":"data:image/jpeg;base64,","B15/q15_189":"data:image/jpeg;base64,","B15/q15_190":"data:image/jpeg;base64,","B15/q15_192":"data:image/jpeg;base64,","B15/q15_193":"data:image/jpeg;base64,","B15/q15_194":"data:image/jpeg;base64,","B15/s15_open":"data:image/jpeg;base64,","B15/s15_g":"data:image/jpeg;base64,","B15/s15_tab":"data:image/jpeg;base64,"}};
